mapper.select:
SELECT d.id, d.name, d.age, d.sex, d.level_id, d.phone, d.hospital, d.account_id,
       d.createtime, d.updatetime, dl.id as lid, dl.name as lname,
       tt.name as tname, tt.id as tid
FROM `doctor` d
left join doctor_level dl on d.level_id = dl.id
left join treat_type tt on d.type_id = tt.id




            OR d.name LIKE #{key}
            OR d.id LIKE #{key}
            OR tt.name LIKE #{key}
            OR d.phone LIKE #{key}
            OR dl.name LIKE #{key}



order by d.id

mapper.update:
